class Solution {
    int maxForChar(const string& s, int k, char target) {
        int l = 0, flips = 0, best = 0;
        for (int r = 0; r < (int)s.size(); ++r) {
            if (s[r] != target) flips++;
            while (flips > k) {
                if (s[l] != target) flips--;
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
public:
    int maxConsecutiveAnswers(string answerKey, int k) {
        return max(maxForChar(answerKey, k, 'T'), maxForChar(answerKey, k, 'F'));
    }
};

class Solution {
    private int maxForChar(String s, int k, char target) {
        int l = 0, flips = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            if (s.charAt(r) != target) flips++;
            while (flips > k) {
                if (s.charAt(l) != target) flips--;
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
    public int maxConsecutiveAnswers(String answerKey, int k) {
        return Math.max(maxForChar(answerKey, k, 'T'), maxForChar(answerKey, k, 'F'));
    }
}

var maxConsecutiveAnswers = function(answerKey, k) {
  function maxForChar(target) {
    let l = 0, flips = 0, best = 0;
    for (let r = 0; r < answerKey.length; r++) {
      if (answerKey[r] !== target) flips++;
      while (flips > k) {
        if (answerKey[l] !== target) flips--;
        l++;
      }
      best = Math.max(best, r - l + 1);
    }
    return best;
  }
  return Math.max(maxForChar('T'), maxForChar('F'));
};
